/* @FileSystemInfo(type = "universalbinary", description = "Mac OSX Universal Binary", factory = typeof(GFileSystemBaseFactory)) */
public class UniversalBinaryFileSystem : GFileSystemBase {

	private FatHeader header;
	private List<GFileImpl> list = new();

	public UniversalBinaryFileSystem(string fileSystemName, ByteProvider provider) : base(fileSystemName, provider)
    {
	}

	/* @Override */
	public FileAttributes getFileAttributes(GFile file, TaskMonitor monitor) {
		int index = list.indexOf(file);
		FileAttributes result = new FileAttributes();
		if (index != -1) {
			result.add(FileAttributeType.COMMENT_ATTR,
				header.getArchitectures().get(index).toString());
		}
		return result;
	}

	/* @Override */
	public List<GFile> getListing(GFile directory)
    {
		return new(list);
	}

	/* @Override */
	public bool isValid(TaskMonitor monitor)
    {
		bool isLittleEndian = false;// always big endian
		BinaryReader reader = new BinaryReader(provider, isLittleEndian);
		int magic = reader.readInt(0);
		int nArch = reader.readInt(4);
		if (magic == FatHeader.FAT_MAGIC || magic == FatHeader.FAT_CIGAM) {
			return nArch < 0x20;
		}
		return false;
	}

	/* @Override */
	public void open(TaskMonitor monitor)
    {
		try {
			header = new FatHeader(provider);
			List<FatArch> architectures = header.getArchitectures();
			foreach (FatArch architecture in architectures) {
				Processor processor =
					CpuTypes.getProcessor(architecture.getCpuType(), architecture.getCpuSubType());
				int bitSize = CpuTypes.getProcessorBitSize(architecture.getCpuType());
				string name = processor + "-" + bitSize + "-cpu0x" +
					Integer.toHexString(architecture.getCpuSubType());
				GFileImpl file =
					GFileImpl.fromFilename(this, root, name, false, architecture.getSize(), null);
				list.add(file);
			}
		}
		catch (Exception e) {
			throw new IOException(e);
		}
	}

	/* @Override */
	public ByteProvider getByteProvider(GFile file, TaskMonitor monitor)
    {

		int index = list.indexOf(file);

		if (index == -1) {
			return null;
		}

		List<FatArch> architectures = header.getArchitectures();

		FatArch architecture = architectures.get(index);

		return new ByteProviderWrapper(provider, architecture.getOffset(), architecture.getSize(),
			file.getFSRL());
	}

	/* @Override */
	public void close()
    {
		base.close();
	}
}
